// Referral request sequence: initial / +3d reminder / +7d final (configurable), SMS+Email.
// Stops on reply, opt-out, referral submitted, or staff-ineligible. Compliance gated in code.
// Plain Date math (version-safe, no $DateTime).
const openH = Number($env.BUSINESS_HOURS_START || 9);
const closeH = Number($env.BUSINESS_HOURS_END || 19);
if (!($now.hour >= openH && $now.hour < closeH)) return []; // quiet/business-hours gate
const days = (($env.REQUEST_DAYS || '0,3,7').split(',')).map(n => Number(n.trim())).filter(n => !isNaN(n));
const channels = (($env.REQUEST_CHANNELS || 'sms,email,sms').split(',')).map(s => s.trim().toLowerCase());
const maxSteps = days.length;
const dailyCap = Number($env.DAILY_CAP || 200);
const biz = $env.BUSINESS_NAME || 'us';
const link = $env.REFERRAL_LINK || $env.BOOKING_LINK || '';
const incentive = ($env.REFERRAL_INCENTIVE || '').trim();
const nowMs = $now.toMillis();
const today = $now.toISODate();
const yes = v => String(v || '').toLowerCase() === 'yes';
const dateOf = v => { const t = new Date(v).getTime(); return isNaN(t) ? '' : new Date(t).toISOString().slice(0,10); };
const rows = $input.all().map(i => i.json);
const sentToday = rows.filter(r => r.Last_Outbound_At && dateOf(r.Last_Outbound_At) === today).length;
let remaining = Math.max(0, dailyCap - sentToday);
const terminal = s => ['opted out','not eligible','referral submitted','complaint','complete'].some(t => s.includes(t));
const out = [];
for (const r of rows) {
  if (remaining <= 0) break;
  if (yes(r.Opted_Out)) continue;
  if (yes(r.Referral_Submitted)) continue;
  if (String(r.Referral_Eligible || '').toLowerCase() !== 'yes') continue;
  if (String(r.Sequence_Active || 'No').toLowerCase() !== 'yes') continue;
  if (r.Last_Inbound_At) continue; // customer replied -> stop
  if (terminal(String(r.Status || '').toLowerCase())) continue;
  const step = Number(r.Sequence_Step || 0);
  if (step >= maxSteps) continue;
  const phone = String(r.Customer_Phone || '').trim();
  const due = r.Next_Request_At ? nowMs >= new Date(r.Next_Request_At).getTime() : false;
  if (!due) continue;
  const nextStep = step + 1;
  const isLast = nextStep >= maxSteps;
  const channel = channels[step] || 'sms';
  const first = r.Customer_Name ? (' ' + String(r.Customer_Name).split(' ')[0]) : '';
  const svc = r.Service_Type ? ` with your ${r.Service_Type}` : '';
  const rewardLine = incentive ? ` As a thank-you, ${incentive}.` : '';
  let sms;
  if (step === 0) sms = `Hi${first}, it's ${biz} — so glad we could help${svc}! If you know someone who'd need us, we'd be grateful for an intro.${rewardLine} Share here: ${link}`.trim();
  else if (isLast) sms = `Hi${first}, last note from ${biz} — no pressure at all. If anyone comes to mind who could use us, here's an easy link: ${link}. Thanks either way!`.trim();
  else sms = `Hi${first}, just a friendly follow-up from ${biz}. Know anyone who'd love the same service? A quick intro means a lot: ${link}`.trim();
  sms = `${sms} Reply STOP to opt out.`;
  const emailSubject = step === 0 ? `A quick favor from ${biz}` : `Following up — ${biz}`;
  const emailBody = `Hi${first},\n\nThank you again for letting ${biz} help you${svc}. If you know someone who'd benefit from the same service, we'd be truly grateful for a referral.${rewardLine}\n\nIt only takes a moment: ${link}\n\nNo pressure at all — thank you either way!\n\n— ${biz}\n\nReply STOP to opt out.`;
  const gaps = days;
  const nextAt = isLast ? '' : $now.plus({ minutes: ((gaps[nextStep] !== undefined ? gaps[nextStep] : 0) - (gaps[step] || 0)) * 1440 }).toISO();
  out.push({ json: { ...r, _channel: (channel === 'email' && r.Customer_Email) ? 'email' : 'sms', _sms_msg: sms, _email_subject: emailSubject, _email_body: emailBody, _next_step: nextStep, _is_last: isLast, _next_request_at: nextAt, _new_status: isLast ? 'Sequence Complete - No Referral' : 'Request Sent' } });
  remaining--;
}
return out;
